import AppKit

/// Official marks from Simple Icons v15.0.0 (assets/logos), converted to vector PDF and embedded
/// so the hand-assembled .app needs no resource bundle. Template images: tinted by the system.
enum Logos {
    static let claude = image(claudePDF)
    static let openAI = image(openAIPDF)

    private static func image(_ base64: String) -> NSImage {
        let img = Data(base64Encoded: base64).flatMap(NSImage.init(data:)) ?? NSImage()
        img.isTemplate = true
        return img
    }

    private static let claudePDF = ""
    private static let openAIPDF = ""
}
